.cm-editor.cm-structure-view {
	.cm-scroller {
		z-index: auto;
	}

	.cm-content {
		z-index: 1;
	}

	.cm-structure-overlay {
		position: absolute;
		z-index : 0;
		overflow: hidden;

		pointer-events: none;
	}

	.code-structure-view {
		display: block;
		width  : 100%;
		height : 100%;
	}
}
